(()=>{
 const root=document.getElementById('ay-sky'),phone=root.querySelector('.phone'),sheet=root.querySelector('.sheet'),shade=root.querySelector('.shade');
 const themes=[['blue','晴空蓝'],['sunset','桃色晚霞'],['night','星夜紫']];
 const choices=[['still','静态'],['drift','轻柔移动'],['glow','流光']];
 const saved=window.openai?.widgetState?.modelContent||{};
 const pref={theme:themes.some(x=>x[0]===saved.theme)?saved.theme:'blue',motion:choices.some(x=>x[0]===saved.motion)?saved.motion:'drift',reduce:saved.reduce===true};
 let appearanceOpen=false,returnFocus=null;const systemReduced=matchMedia('(prefers-reduced-motion: reduce)');
 const icons=()=>globalThis.lucide?.createIcons({attrs:{'stroke-width':1.75}});
 function apply(){const paused=pref.reduce||systemReduced.matches;const heading=sheet.querySelector('[data-motion-title]');if(heading)heading.textContent=paused?'背景动态 · 已暂停':'背景动态';sheet.querySelectorAll('[data-motion-choice]').forEach(b=>b.disabled=paused);phone.dataset.theme=pref.theme;phone.dataset.motion=pref.motion;phone.classList.toggle('reduce',pref.reduce);phone.style.removeProperty('--accent');root.querySelectorAll('.sky-art').forEach(n=>n.classList.toggle('is-active',n.dataset.background===pref.theme));}
 function persist(){if(window.openai?.setWidgetState)Promise.resolve(window.openai.setWidgetState({modelContent:{...pref},privateContent:null})).catch(()=>{});}
 function sync(){root.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===pref.theme)));root.querySelectorAll('[data-motion-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.motionChoice===pref.motion)));const toggle=sheet.querySelector('[data-appearance-reduce]');if(toggle)toggle.setAttribute('aria-pressed',String(pref.reduce));apply();persist();}
 function show(trigger){sheet.dataset.panel='appearance';returnFocus=trigger;appearanceOpen=true;sheet.innerHTML=`<div class="handle"></div><div class="sheethead"><button data-appearance-close aria-label="关闭外观设置"><i class="icon" data-lucide="x"></i></button><h2>外观</h2><span style="width:44px"></span></div><h3 class="appearance-title">应用主题</h3><div class="theme-grid">${themes.map(([id,name])=>`<button class="theme-choice" data-theme-choice="${id}" aria-pressed="${pref.theme===id}"><span class="thumbnail" style="--landscape:var(--image-${id})"></span><span class="selected-mark"><i class="icon" data-lucide="check"></i></span>${name}</button>`).join('')}</div><h3 class="appearance-title" data-motion-title>背景动态</h3><div class="motion-choices">${choices.map(([id,name])=>`<button data-motion-choice="${id}" aria-pressed="${pref.motion===id}">${name}<i class="mode-check" data-lucide="check" aria-hidden="true"></i></button>`).join('')}</div><button class="appearance-toggle" data-appearance-reduce aria-pressed="${pref.reduce}">减少动态效果<span class="switch-track" aria-hidden="true"></span></button>`;sheet.inert=false;sheet.classList.remove('leaving');shade.classList.add('open');sheet.classList.add('open');apply();icons();sheet.querySelector('button').focus({preventScroll:true});}
 function close(){appearanceOpen=false;sheet.classList.add('leaving');sheet.classList.remove('open');shade.classList.remove('open');sheet.inert=true;returnFocus?.focus({preventScroll:true});}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.action==='appearance'){e.stopPropagation();show(b);return}if(!appearanceOpen)return;if(e.target===shade||b?.hasAttribute('data-appearance-close')){e.stopPropagation();close();return}if(b?.dataset.themeChoice){e.stopPropagation();pref.theme=b.dataset.themeChoice;sync()}else if(b?.dataset.motionChoice){e.stopPropagation();pref.motion=b.dataset.motionChoice;sync()}else if(b?.hasAttribute('data-appearance-reduce')){e.stopPropagation();pref.reduce=!pref.reduce;sync()}},true);
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.action==='reduce'){e.stopPropagation();pref.reduce=!pref.reduce;apply();persist();const label=b.querySelector('span');if(label)label.textContent=pref.reduce?'已开启':'未开启'}else if(b?.dataset.action==='settings'){queueMicrotask(()=>{const label=sheet.querySelector('[data-action="reduce"] span');if(label)label.textContent=pref.reduce?'已开启':'未开启'})}},true);
 root.addEventListener('keydown',e=>{if(appearanceOpen&&e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}},true);
 const observer=new MutationObserver(()=>{if(appearanceOpen&&!sheet.classList.contains('open')){appearanceOpen=false;returnFocus?.focus({preventScroll:true})}});observer.observe(sheet,{attributes:true,attributeFilter:['class']});
 systemReduced.addEventListener('change',apply);apply();
 let scrollPause;root.addEventListener('scroll',e=>{if(e.target.matches?.('.feed,.memory-list,.task-list,.sheet')){phone.classList.add('reading-motion');clearTimeout(scrollPause);scrollPause=setTimeout(()=>phone.classList.remove('reading-motion'),180)}},true);
})();
